window.products.push({"id":458532,"name":"Harrisburg Toddler Bed (Espresso)","category":"homeandappliances","retail price":119.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71sdf8skWrL._AC_SL1500_.jpg","description":"SAFE AND SECURE—The Harrisburg Toddler Bed by BK Furniture provides an exciting next step for your little one with a simple design that emphasizes safety. Two large side rails help prevent your child from rolling out of bed, while providing enough space for them to climb in and out independently. STURDY CONSTRUCTION — Solid wood construction provides lasting durability for years of use. Durable finish wipes clean easily with a damp cloth. QUICK & EASY ASSEMBLY — Assembles in minutes with all necessary tools included. Headboard, footboard, and two side safety rails included. COLORFUL OPTIONS — Additional colors available to suit your child's preference. Finished in child-safe, non-toxic paints and materials. Safety Tested to ASTM F963-17 and 16 CFY Part 1307 for lead, heavy metals, and phthalates. Suitable for ages 1.5 to 5-years-old Note: Mattress not included.","images":["https://m.media-amazon.com/images/I/71sdf8skWrL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Rack Furniture","source_asin":"B072F8BL7L","category_path":"Home & Kitchen"},"sku":"BM-458532","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B072F8BL7L","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B072F8BL7L","price_pending":true,"merchant_ready":false});
